import json, re
from collections import Counter
from pathlib import Path
P = "-Users-muskanpaliwal-Work-open-source-entire-cli-"
S = {"2408":("fix-checkpoint-metadata-followups","abe1c187-267b-4b4f-b725-fadd2a7a3805"),"2385":("fix-session-cleanup-safety","199968ec-b436-42a9-a200-2e8047b7fa3f"),"2320":("refactor-remaining-git-metadata-consumers","2dcc668d-056f-4597-b574-fe43fa893816"),"2305":("refactor-strategy-hook-metadata-resolution","8867ef32-5632-4e28-bca2-738aecfa238d"),"2259":("fix-trailer-writer-grammar","bc3474e1-dc28-449a-9307-1c33bd90aa33"),"2253":("fix-checkpoint-trailer-block","8e50718b-7c6e-42e7-b849-107a698e5c42"),"2190":("refactor-git-metadata-traversal","52a3b82d-f0d8-4d8c-b002-61a1207f48ef"),"2131":("improve-process-sessions-condensation","b105bf31-8732-4719-a37e-bb39c57b394f"),"2099":("fix-claude-transcript-readiness","653ef2d5-58cc-46f7-828d-f03beb1199d4"),"2053":("refactor-streaming-atomic-write","01c3e971-6dcb-42fb-b774-5200bc4fda77"),"2027":("fix-opencode-user-prompt-events","ea8e8726-32ca-43d2-8f95-e6133917d552")}
tot = Counter()
for pr,(wt,sid) in S.items():
    tools = Counter(); showfile = showrev = 0; graph = why = blame = 0; search_ids = {}
    results = {}
    recs = [json.loads(l) for l in open(f"./{P}{wt}/{sid}.jsonl") if l.strip()]
    for r in recs:
        c = r.get("message",{}).get("content")
        if not isinstance(c, list): continue
        for p in c:
            if not isinstance(p, dict): continue
            if p.get("type")=="tool_use":
                tools[p["name"]] += 1
                if p["name"]=="Bash":
                    cmd = p["input"].get("command","")
                    for m in re.finditer(r"git(?:\s+-C\s+\S+)*\s+show\s+(\S+)", cmd):
                        if ":" in m.group(1) and not m.group(1).startswith("-"): showfile += 1
                        else: showrev += 1
                    graph += len(re.findall(r"\bentire\s+graph\b", cmd))
                    why += len(re.findall(r"\bentire\s+why\b", cmd))
                    blame += len(re.findall(r"\bentire\s+blame\b", cmd))
                    if re.search(r"\bentire\s+search\b", cmd): search_ids[p["id"]] = cmd
            elif p.get("type")=="tool_result" and p.get("tool_use_id") in search_ids:
                out = p.get("content")
                if isinstance(out, list): out = " ".join(x.get("text","") for x in out if isinstance(x, dict))
                results[p["tool_use_id"]] = (out or "")[:300].replace("\n"," | ")
    print(f"#{pr} tools={dict(tools.most_common(8))}")
    print(f"     git show path@rev={showfile} git show commit={showrev} entire graph={graph} why={why} blame={blame}")
    for k,v in results.items(): print("     entire search ->", v)
    tot.update(tools)
print("TOTAL tools", dict(tot.most_common(10)))
EOF
